// The user is the connection's, never the frame's: the validator has already dropped any userId a client sent.
async function answerListSessions(
  ws: WebSocket,
  session: ChatSession,
  {limit, before}: ListSessionsMessage,
  sessionStore: SessionStore | undefined
): Promise<void> {
  const summaries = (await sessionStore?.listFor?.(session.userId, {limit, before})) ?? [];
